import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
// Shared with Delayed Recognition Memory (§A.4) — same rendering used for
// the original encoding AND the later retest, so it's a faithful re-display
// of the actual face, not a copy that could drift. See
// src/features/games/lib/FaceAvatar.jsx.
import SharedFaceAvatar from "../../lib/FaceAvatar.jsx";
import { StudyItemRegistry } from "../../lib/studyItemRegistry.js";

/* =========================================================================
   NeuroTrack — Face Recognition Memory Test
   Episodic visual memory / facial identity recognition screening module.
   Same clinical instrumentation design language as the rest of the
   NeuroTrack suite (Trail Making Test, Go/No-Go Test): navy/blue
   diagnostic palette, monospaced data tiles, a single deliberate motion
   cue, no game-like feedback during the scored assessment.
   ========================================================================= */

/* ---------------------------- Configuration ------------------------------ */
// Was 20 — the "Please wait… recognition begins in Ns" screen shown
// between studying the face(s) and being asked to identify them. Separate
// from RECOGNITION_TIME_SEC below (the actual selection window, already
// 12s) — this is just the wait beforehand.
const DELAY_SEC = 12;
// Was one timeFor(n) = n*5s used for both viewing AND recognition alike
// (1->5s, 2->10s, 3->15s, 4->20s) — reported as too long, particularly the
// recognition (choosing) phase. Split into two, each with its own cap:
// viewing still scales down for fewer faces, just with a lower ceiling now
// that studyCount tops out at 3, not 4; recognition is a flat window
// regardless of how many faces are shown, not a scaling one.
const viewTimeFor = (faceCount) => 2 + faceCount * 2; // 1->4s, 2->6s, 3->8s
const RECOGNITION_TIME_SEC = 12;

const DOMAINS = [
  "Face Recognition Memory", "Episodic Visual Memory", "Facial Identity Recognition",
  "Visual Recognition", "Attention", "Processing Speed", "Memory Retention", "Temporal Lobe Function",
];

/* ============================ Business logic =============================
   Pure functions only — face generation, trial planning, validation, and
   metric calculation never touch React state directly. Screens call these
   and render the results.
   ========================================================================= */

function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function uid(prefix) { return `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`; }
function mean(arr) { return arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0; }
function stddev(arr) {
  if (arr.length < 2) return 0;
  const m = mean(arr);
  return Math.sqrt(mean(arr.map((v) => (v - m) * (v - m))));
}
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

/* ============================================================
   PRIVATE PHOTO LIBRARY — local-only personalization
   ============================================================
   Patients may optionally upload up to MAX_PATIENT_PHOTOS of their own
   photos so the recognition test can be personalized with faces they
   actually know, instead of only synthetic ones.

   Storage model: photos are written to this browser's IndexedDB only,
   namespaced under the current patient's auto-generated, device-local
   patientId. Nothing is uploaded to a server - there is none in this
   module - so a photo can never be shown to a different patient unless
   they are physically using the same browser profile under the same
   patientId. The UI never exposes a download/export/share action for a
   stored photo; photos are only ever rendered inline as a face stimulus
   inside that same patient's own test session. (This is a client-side,
   good-faith boundary - like any browser data, it is only as private as
   the device it lives on, not a cryptographic guarantee.)
   ========================================================================= */
const MAX_PATIENT_PHOTOS = 100;

// --- IN-CHAT PREVIEW NOTE -------------------------------------------------
// The delivered project (FaceRecognitionTest-v2.jsx / the Vite project in
// your folder) stores each patient's uploaded photos in IndexedDB, keyed to
// a localStorage-persisted patientId, so the library survives reloads and
// stays private per browser profile. Claude artifacts aren't allowed to use
// localStorage/IndexedDB, so THIS PREVIEW COPY keeps the exact same
// in-app behavior (upload, downscale, use in trials, delete, never
// exportable) but holds photos in React state only - they reset if you
// reload this artifact. Nothing about the test logic, scoring, or the
// AI-image-pool integration differs from the delivered file.
// ---------------------------------------------------------------------------
function getOrCreatePatientId() {
  return uid("patient"); // in-memory only in this preview
}

/** Downscales an uploaded image to a small square dataURL before storage,
 *  both to keep IndexedDB usage reasonable across up to 100 photos and to
 *  normalize every photo to the same presentation size as the synthetic
 *  faces it will sit alongside in the recognition grid. */
function downscaleImageFile(file, size) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error);
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Could not read image"));
      img.onload = () => {
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        const scale = Math.max(size / img.width, size / img.height);
        const dw = img.width * scale, dh = img.height * scale;
        ctx.drawImage(img, (size - dw) / 2, (size - dh) / 2, dw, dh);
        resolve(canvas.toDataURL("image/jpeg", 0.85));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

/* ---------- Synthetic face generation ----------
   Generates fully synthetic, anonymous, procedurally-drawn faces. No
   photographs, no real or celebrity likenesses are ever used — every face
   is composed from parametric shape/color primitives. */
const SKIN_TONES = ["#F5D6B8", "#EFC49B", "#DCA772", "#C88A54", "#A5673A", "#7A4A2B"];
const HAIR_COLORS = ["#241812", "#4A2E1E", "#7A4A24", "#A9702F", "#C9A876", "#5B5B5B", "#1A1A1A", "#8A5A3B"];
const EYE_COLORS = ["#4A372A", "#3E6E96", "#4E7A44", "#6B4226", "#5A5A5A"];
const HAIR_STYLES = ["short", "side-part", "curly", "bun", "bald", "medium"];
const FACE_SHAPES = ["oval", "round", "square", "heart"];
const EYEBROW_STYLES = ["straight", "arched", "thick", "thin"];
const AGE_GROUPS = ["young", "middle", "senior"];
const NOSE_WIDTHS = [7, 9, 11, 13];
const MOUTH_WIDTHS = [26, 32, 38, 44];

const FIELD_POOLS = {
  ageGroup: AGE_GROUPS, skinTone: SKIN_TONES, hairColor: HAIR_COLORS, hairStyle: HAIR_STYLES,
  eyeColor: EYE_COLORS, faceShape: FACE_SHAPES, eyebrowStyle: EYEBROW_STYLES,
  noseWidth: NOSE_WIDTHS, mouthWidth: MOUTH_WIDTHS,
};
const FIELD_KEYS = Object.keys(FIELD_POOLS);

function randomFaceParams() {
  const p = {};
  FIELD_KEYS.forEach((k) => { p[k] = pick(FIELD_POOLS[k]); });
  return p;
}
function faceSignature(face) { return FIELD_KEYS.map((k) => face[k]).join("|"); }
function generateFace() { return { id: uid("face"), kind: "synthetic", ...randomFaceParams() }; }

/** Generates a face whose feature signature has not been used before in this trial. */
function generateDistinctFace(usedSignatures) {
  let face, sig, attempts = 0;
  do {
    face = generateFace();
    sig = faceSignature(face);
    attempts++;
  } while (usedSignatures.has(sig) && attempts < 25);
  usedSignatures.add(sig);
  return face;
}

/** Creates a near-duplicate of a base face by changing only `numChanges` features.
 *  Used to build visually-similar distractors for Medium/Hard difficulty. */
function mutateFace(baseFace, numChanges) {
  const clone = { ...baseFace, id: uid("face") };
  const fieldsToChange = shuffle(FIELD_KEYS).slice(0, numChanges);
  fieldsToChange.forEach((k) => {
    const pool = FIELD_POOLS[k].filter((v) => v !== baseFace[k]);
    clone[k] = pool.length ? pick(pool) : baseFace[k];
  });
  return clone;
}

/* ---------- Trial planning ----------
   Builds the randomized, difficulty-progressive trial plan. */
function buildPracticePlan() {
  return [
    { difficulty: "easy", studyCount: 1, recognitionCount: 4, viewingTimeSec: viewTimeFor(1), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: true },
    { difficulty: "easy", studyCount: 1, recognitionCount: 4, viewingTimeSec: viewTimeFor(1), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: true },
  ];
}
// Was 8 scored trials (2 each of studyCount 1/2/3/4) — reported as too
// many. Now 5, spanning 3 study-set sizes (1, 2, 3 faces to remember) —
// "1 set, 2 set, 3 set" — instead of 4; the studyCount-4/recognitionCount-10
// tier is dropped rather than shortened, not just trimmed evenly across
// every tier.
function buildScoredPlan() {
  return [
    { difficulty: "easy", studyCount: 1, recognitionCount: 4, viewingTimeSec: viewTimeFor(1), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: false },
    { difficulty: "medium", studyCount: 2, recognitionCount: 6, viewingTimeSec: viewTimeFor(2), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: false },
    { difficulty: "medium", studyCount: 2, recognitionCount: 6, viewingTimeSec: viewTimeFor(2), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: false },
    { difficulty: "hard", studyCount: 3, recognitionCount: 8, viewingTimeSec: viewTimeFor(3), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: false },
    { difficulty: "hard", studyCount: 3, recognitionCount: 8, viewingTimeSec: viewTimeFor(3), recognitionMaxSec: RECOGNITION_TIME_SEC, isPractice: false },
  ];
}

