/** For a given trial config, produces the study faces (targets) and the
 *  full randomized recognition grid (targets + distractors). */
/**
 * For a given trial config, produces the study faces (targets) and the
 * full randomized recognition grid (targets + distractors).
 *
 * Face source priority, per trial:
 *   1. Patient's own uploaded photos (PRIVATE PHOTO LIBRARY) - if the
 *      patient has uploaded enough unused photos to fully fill this
 *      trial's grid, there is a random 60% chance the trial is drawn from
 *      their private library instead - "randomly personalized", never
 *      guaranteed. Scored assessment only (see call sites in the hook).
 *   2. AI-generated face image pool (public/faces/, auto-discovered at
 *      build time into faceManifest.js / AI_FACE_POOL) - this is the
 *      default, non-personalized face dataset for the test, used for both
 *      practice and scored trials whenever personalization doesn't apply.
 *      Images are chosen per-trial (not globally exclusive across the
 *      whole session) since the pool is a fixed, finite set of real image
 *      files rather than an unbounded synthetic generator - but every
 *      recognition grid is guaranteed to contain no duplicate image.
 *   3. Procedurally generated synthetic SVG faces - safety-net fallback
 *      only, used if neither of the above can fill the grid (e.g. the
 *      public/faces/ pool is empty or a trial needs more faces than exist).
 *
 * usedPhotoIds is mutated in place so a personal photo is never repeated
 * within one test session.
 */
function generateTrialData(config, photoPool = [], usedPhotoIds = new Set(), aiPool = AI_FACE_POOL) {
  const availablePhotos = photoPool.filter((p) => !usedPhotoIds.has(p.id));
  const canPersonalize = availablePhotos.length >= config.recognitionCount && Math.random() < 0.6;

  if (canPersonalize) {
    const chosen = shuffle(availablePhotos).slice(0, config.recognitionCount);
    chosen.forEach((p) => usedPhotoIds.add(p.id));
    const studyFaces = chosen.slice(0, config.studyCount).map((p) => ({ id: p.id, kind: "photo", dataURL: p.dataURL }));
    const distractorFaces = chosen.slice(config.studyCount).map((p) => ({ id: p.id, kind: "photo", dataURL: p.dataURL }));
    const recognitionFaces = shuffle([
      ...studyFaces.map((f) => ({ ...f, isTarget: true })),
      ...distractorFaces.map((f) => ({ ...f, isTarget: false })),
    ]);
    return { studyFaces, recognitionFaces, config, personalized: true, source: "personal" };
  }

  const canUseAiPool = Array.isArray(aiPool) && aiPool.length >= config.recognitionCount;
  if (canUseAiPool) {
    const chosen = shuffle(aiPool).slice(0, config.recognitionCount);
    const studyFaces = chosen.slice(0, config.studyCount).map((p) => ({ id: p.id, kind: "photo", dataURL: p.dataURL }));
    const distractorFaces = chosen.slice(config.studyCount).map((p) => ({ id: p.id, kind: "photo", dataURL: p.dataURL }));
    const recognitionFaces = shuffle([
      ...studyFaces.map((f) => ({ ...f, isTarget: true })),
      ...distractorFaces.map((f) => ({ ...f, isTarget: false })),
    ]);
    return { studyFaces, recognitionFaces, config, personalized: false, source: "ai-pool" };
  }

  const usedSignatures = new Set();
  const studyFaces = [];
  for (let i = 0; i < config.studyCount; i++) studyFaces.push(generateDistinctFace(usedSignatures));

  const distractorCount = config.recognitionCount - config.studyCount;
  const distractors = [];
  for (let i = 0; i < distractorCount; i++) {
    let distractor;
    if (config.difficulty === "easy") {
      distractor = generateDistinctFace(usedSignatures);
    } else {
      const base = studyFaces[i % studyFaces.length];
      const numChanges = config.difficulty === "hard" ? 2 : 4; // hard = closer resemblance
      let attempts = 0, sig;
      do {
        distractor = mutateFace(base, numChanges);
        sig = faceSignature(distractor);
        attempts++;
      } while (usedSignatures.has(sig) && attempts < 10);
      usedSignatures.add(sig);
    }
    distractors.push(distractor);
  }

  const recognitionFaces = shuffle([
    ...studyFaces.map((f) => ({ ...f, isTarget: true })),
    ...distractors.map((f) => ({ ...f, isTarget: false })),
  ]);

  return { studyFaces, recognitionFaces, config, personalized: false, source: "synthetic" };
}

/** Compares the participant's selections against ground truth. */
function validateSelection(selectedIds, recognitionFaces) {
  const targetIds = recognitionFaces.filter((f) => f.isTarget).map((f) => f.id);
  const distractorIds = recognitionFaces.filter((f) => !f.isTarget).map((f) => f.id);

  const hits = selectedIds.filter((id) => targetIds.includes(id)).length;
  const misses = targetIds.length - hits;
  const falsePositives = selectedIds.filter((id) => distractorIds.includes(id)).length;
  const correctRejections = distractorIds.length - falsePositives;
  const fullyCorrect = hits === targetIds.length && falsePositives === 0;

  return { hits, misses, falsePositives, correctRejections, targetsCount: targetIds.length, distractorsCount: distractorIds.length, fullyCorrect };
}

/** Aggregates all scored-trial responses into the standardized metric set. */
function calculateMetrics(responses) {
  const totalTargets = responses.reduce((s, r) => s + r.targetsCount, 0);
  const totalDistractors = responses.reduce((s, r) => s + r.distractorsCount, 0);
  const totalHits = responses.reduce((s, r) => s + r.hits, 0);
  const totalMisses = responses.reduce((s, r) => s + r.misses, 0);
  const totalFP = responses.reduce((s, r) => s + r.falsePositives, 0);
  const totalCR = responses.reduce((s, r) => s + r.correctRejections, 0);

  const hitRate = totalTargets ? totalHits / totalTargets : 0;
  const missRate = totalTargets ? totalMisses / totalTargets : 0;
  const falsePositiveRate = totalDistractors ? totalFP / totalDistractors : 0;
  const correctRejectionRate = totalDistractors ? totalCR / totalDistractors : 0;
  const faceRecognitionAccuracy = (totalTargets + totalDistractors) ? ((totalHits + totalCR) / (totalTargets + totalDistractors)) * 100 : 0;

  const reactionTimes = responses.map((r) => r.reactionTimeMs);
  const averageReactionTime = mean(reactionTimes);
  const fastestReactionTime = reactionTimes.length ? Math.min(...reactionTimes) : 0;
  const slowestReactionTime = reactionTimes.length ? Math.max(...reactionTimes) : 0;
  const reactionTimeVariability = stddev(reactionTimes);
  const timeouts = responses.filter((r) => r.timedOut).length;
  const incorrectSelections = totalFP + totalMisses;

  const byDifficulty = (diff) => responses.filter((r) => r.difficulty === diff);
  const accuracyFor = (subset) => {
    const t = subset.reduce((s, r) => s + r.targetsCount, 0);
    const d = subset.reduce((s, r) => s + r.distractorsCount, 0);
    const h = subset.reduce((s, r) => s + r.hits, 0);
    const c = subset.reduce((s, r) => s + r.correctRejections, 0);
    return (t + d) ? ((h + c) / (t + d)) * 100 : 0;
  };

  const easy = byDifficulty("easy"), medium = byDifficulty("medium"), hard = byDifficulty("hard");
  const faceEncodingScore = accuracyFor(easy);
  const faceRecognitionScore = hitRate * 100;
  const faceRetentionScore = accuracyFor(hard);
  const visualRecognitionScore = correctRejectionRate * 100;
  const attentionConsistency = clamp(100 - (averageReactionTime ? (reactionTimeVariability / averageReactionTime) * 100 : 0), 0, 100);
  const processingSpeedScore = clamp(100 - (Math.max(0, averageReactionTime - 2000) / (20000 - 2000)) * 100, 0, 100);

  const rawScore = totalHits - totalFP;
  const normalizedScore = totalTargets ? clamp((rawScore / totalTargets) * 100, 0, 100) : 0;

  const weights = { faceEncodingScore: 0.15, faceRecognitionScore: 0.25, faceRetentionScore: 0.20, visualRecognitionScore: 0.15, attentionConsistency: 0.10, processingSpeedScore: 0.15 };
  const cognitiveScoreRaw =
    faceEncodingScore * weights.faceEncodingScore + faceRecognitionScore * weights.faceRecognitionScore +
    faceRetentionScore * weights.faceRetentionScore + visualRecognitionScore * weights.visualRecognitionScore +
    attentionConsistency * weights.attentionConsistency + processingSpeedScore * weights.processingSpeedScore;
  const cognitiveScore = Math.round(clamp(cognitiveScoreRaw, 0, 100));

  return {
    faceRecognitionAccuracy, hitRate: hitRate * 100, missRate: missRate * 100,
    falsePositiveRate: falsePositiveRate * 100, correctRejectionRate: correctRejectionRate * 100,
    averageReactionTime, fastestReactionTime, slowestReactionTime, reactionTimeVariability,
    timeouts, incorrectSelections,
    faceEncodingScore, faceRecognitionScore, faceRetentionScore, visualRecognitionScore,
    attentionConsistency, processingSpeedScore,
    rawScore, normalizedScore, cognitiveScore,
    byDifficultyAccuracy: { easy: accuracyFor(easy), medium: accuracyFor(medium), hard: accuracyFor(hard) },
    byDifficultyBreakdown: {
      easy: { hits: easy.reduce((s, r) => s + r.hits, 0), misses: easy.reduce((s, r) => s + r.misses, 0), falsePositives: easy.reduce((s, r) => s + r.falsePositives, 0) },
      medium: { hits: medium.reduce((s, r) => s + r.hits, 0), misses: medium.reduce((s, r) => s + r.misses, 0), falsePositives: medium.reduce((s, r) => s + r.falsePositives, 0) },
      hard: { hits: hard.reduce((s, r) => s + r.hits, 0), misses: hard.reduce((s, r) => s + r.misses, 0), falsePositives: hard.reduce((s, r) => s + r.falsePositives, 0) },
    },
  };
}

/** Maps the composite cognitive score into a plain-language interpretation.
 *  NOTE: placeholder cutoffs for the software architecture — require
 *  calibration against a normed reference population before clinical use. */
function interpretScore(cognitiveScore) {
  let interpretation, severity;
  if (cognitiveScore >= 85) {
    interpretation = "Face recognition memory performance falls within the expected range. Encoding, retention, and discrimination of unfamiliar faces were all consistent with typical performance.";
    severity = "Normal";
  } else if (cognitiveScore >= 70) {
    interpretation = "Mild difficulty was observed in face recognition memory, most notably under higher-interference conditions. This may reflect normal variability but could warrant monitoring over time.";
    severity = "Mild Concern";
  } else if (cognitiveScore >= 50) {
    interpretation = "Moderate difficulty was observed across face encoding, retention, and/or discrimination. Performance on this screening task is below the expected range.";
    severity = "Moderate Concern";
  } else {
    interpretation = "Significant difficulty was observed across most aspects of face recognition memory. Performance on this screening task is substantially below the expected range.";
    severity = "Significant Concern";
  }
  return { interpretation, severity, disclaimer: "NeuroTrack is a cognitive screening prototype and does not provide a medical diagnosis. Results should be discussed with a qualified healthcare professional." };
}

/** Assembles the final, standardized NeuroTrack assessment report. Field
 *  names and shape must not be altered so that every NeuroTrack module
 *  returns a report the platform can aggregate identically. */
function buildResultModel({ sessionId, responses, clickHistory, startedAt, completedAt }) {
  const metrics = calculateMetrics(responses);
  const { interpretation, severity, disclaimer } = interpretScore(metrics.cognitiveScore);
  const errors = responses.reduce((s, r) => s + r.misses + r.falsePositives, 0);

  return {
    testName: "Face Recognition Memory Test",
    sessionId,
    testVersion: "NeuroTrack-FRMT-1.0",
    domains: DOMAINS,
    completionTime: completedAt - startedAt,
    accuracy: metrics.faceRecognitionAccuracy,
    errors,
    completed: true,
    averageReactionTime: metrics.averageReactionTime,
    fastestReactionTime: metrics.fastestReactionTime,
    slowestReactionTime: metrics.slowestReactionTime,
    rawScore: metrics.rawScore,
    normalizedScore: metrics.normalizedScore,
    cognitiveScore: metrics.cognitiveScore,
    interpretation, severity, disclaimer,
    clickHistory,
    metrics: {
      faceRecognitionAccuracy: metrics.faceRecognitionAccuracy,
      hitRate: metrics.hitRate, missRate: metrics.missRate,
      falsePositiveRate: metrics.falsePositiveRate, correctRejectionRate: metrics.correctRejectionRate,
      faceEncodingScore: metrics.faceEncodingScore, faceRecognitionScore: metrics.faceRecognitionScore,
      faceRetentionScore: metrics.faceRetentionScore, visualRecognitionScore: metrics.visualRecognitionScore,
      attentionConsistency: metrics.attentionConsistency, processingSpeedScore: metrics.processingSpeedScore,
      timeouts: metrics.timeouts, incorrectSelections: metrics.incorrectSelections,
      byDifficultyAccuracy: metrics.byDifficultyAccuracy, byDifficultyBreakdown: metrics.byDifficultyBreakdown,
      responses,
    },
  };
}

