/* -------------------- Shared trial header pieces -------------------- */
// DifficultyChip (showed "easy"/"medium"/"hard" in the live trial HUD) was
// removed from both call sites below, not just hidden — the tier still
// drives trial generation, it's just never announced mid-task.
function TimerBar({ remaining, total }) {
  const pct = total ? clamp((remaining / total) * 100, 0, 100) : 0;
  const low = total ? remaining <= total * 0.25 : false;
  return (
    <div className="timer-wrap">
      <div className="timer-track"><div className={`timer-fill ${low ? "timer-fill--low" : ""}`} style={{ width: `${pct}%` }} /></div>
      <span className="timer-text">{Math.ceil(remaining)}s</span>
    </div>
  );
}

