/* ---------------------- charts (hand-rolled SVG) ---------------------- */
function AccuracyByDifficultyChart({ byDifficultyAccuracy }) {
  const rows = [
    { label: "Easy", value: byDifficultyAccuracy.easy, color: "var(--nt-color-go, #12805A)" },
    { label: "Medium", value: byDifficultyAccuracy.medium, color: "#B7791F" },
    { label: "Hard", value: byDifficultyAccuracy.hard, color: "#C7433F" },
  ];
  return (
    <div className="dashboard-section">
      <h2 className="dashboard-section-title">Recognition Accuracy by Difficulty</h2>
      <svg viewBox="0 0 480 140" width="100%" height="140">
        {rows.map((r, i) => {
          const y = i * 44 + 10;
          const w = (clamp(r.value, 0, 100) / 100) * 380;
          return (
            <g key={r.label}>
              <text x="0" y={y + 13} fontSize="12" fontWeight="700" fill="#0F2540">{r.label}</text>
              <rect x="60" y={y} width="380" height="20" rx="6" fill="#EEF2F6" />
              <rect x="60" y={y} width={w} height="20" rx="6" fill={r.color} />
              <text x={70 + w} y={y + 14} fontSize="11" fontWeight="700" fill="#0F2540">{r.value.toFixed(0)}%</text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

function ReactionTimeChart({ responses }) {
  const w = 620, h = 160, pad = 30;
  const maxRt = Math.max(...responses.map((r) => r.reactionTimeMs), 1000);
  const colorFor = (d) => (d === "easy" ? "#12805A" : d === "medium" ? "#B7791F" : "#C7433F");
  const stepX = (w - pad * 2) / Math.max(responses.length - 1, 1);
  const points = responses.map((r, i) => {
    const x = pad + i * stepX;
    const y = h - pad - (r.reactionTimeMs / maxRt) * (h - pad * 2);
    return { x, y, r };
  });
  const path = points.map((p, i) => (i === 0 ? "M" : "L") + p.x.toFixed(1) + " " + p.y.toFixed(1)).join(" ");
  return (
    <div className="dashboard-section">
      <h2 className="dashboard-section-title">Response Time per Trial</h2>
      <svg viewBox={`0 0 ${w} ${h}`} width="100%" height="160">
        <line x1={pad} y1={h - pad} x2={w - pad} y2={h - pad} stroke="#DDE5F0" />
        <path d={path} fill="none" stroke="#2E5FDC" strokeWidth="2" />
        {points.map((p, i) => (
          <circle key={i} cx={p.x} cy={p.y} r="4.5" fill={colorFor(p.r.difficulty)} stroke="white" strokeWidth="1.5" />
        ))}
      </svg>
      <div className="chart-legend">
        <span className="legend-item"><i style={{ background: "#12805A" }} />Easy</span>
        <span className="legend-item"><i style={{ background: "#B7791F" }} />Medium</span>
        <span className="legend-item"><i style={{ background: "#C7433F" }} />Hard</span>
      </div>
    </div>
  );
}

function DifficultyBreakdownChart({ byDifficultyBreakdown }) {
  const diffs = ["easy", "medium", "hard"];
  const colors = { hits: "#12805A", misses: "#B7791F", falsePositives: "#C7433F" };
  return (
    <div className="dashboard-section">
      <h2 className="dashboard-section-title">Difficulty-wise Performance (Hits / Misses / False Positives)</h2>
      <svg viewBox="0 0 480 150" width="100%" height="150">
        {diffs.map((d, i) => {
          const b = byDifficultyBreakdown[d];
          const total = b.hits + b.misses + b.falsePositives || 1;
          const barW = 300, x = 90, y = i * 44 + 10;
          let cursor = x;
          const segs = [{ key: "hits", val: b.hits }, { key: "misses", val: b.misses }, { key: "falsePositives", val: b.falsePositives }];
          return (
            <g key={d}>
              <text x="0" y={y + 13} fontSize="12" fontWeight="700" fill="#0F2540" style={{ textTransform: "capitalize" }}>{d}</text>
              <rect x={x} y={y} width={barW} height="20" rx="6" fill="#EEF2F6" />
              {segs.map((s) => {
                const segW = (s.val / total) * barW;
                const rect = <rect key={s.key} x={cursor} y={y} width={segW} height="20" fill={colors[s.key]} />;
                cursor += segW;
                return rect;
              })}
            </g>
          );
        })}
      </svg>
      <div className="chart-legend">
        <span className="legend-item"><i style={{ background: "#12805A" }} />Hits</span>
        <span className="legend-item"><i style={{ background: "#B7791F" }} />Misses</span>
        <span className="legend-item"><i style={{ background: "#C7433F" }} />False positives</span>
      </div>
    </div>
  );
}

