/* ============================ Orchestration hook ============================
   Single orchestration hook. All state, timers, and business-logic calls
   live here; every screen above is presentation-only. */
const SCREENS = {
  INSTRUCTIONS: "instructions", LIBRARY: "library", COUNTDOWN: "countdown", OBSERVATION: "observation",
  DELAY: "delay", RECOGNITION: "recognition", FEEDBACK: "feedback", COMPLETION: "completion",
};

function useFaceRecognitionTest() {
  const [screen, setScreen] = useState(SCREENS.INSTRUCTIONS);
  const [phase, setPhase] = useState("practice");
  const [plan, setPlan] = useState([]);
  const [trialIndex, setTrialIndex] = useState(0);
  const [trialData, setTrialData] = useState(null);
  const [selectedIds, setSelectedIds] = useState([]);
  const [countdownValue, setCountdownValue] = useState(3);
  const [timeRemaining, setTimeRemaining] = useState(0);
  const [lastFeedback, setLastFeedback] = useState(null);
  const [, setResponses] = useState([]);
  const [result, setResult] = useState(null);

  const [photoLibrary, setPhotoLibrary] = useState([]);
  const [libraryBusy, setLibraryBusy] = useState(false);
  const [libraryError, setLibraryError] = useState(null);
  const patientIdRef = useRef(null);
  if (patientIdRef.current === null) patientIdRef.current = getOrCreatePatientId();
  const usedPhotoIdsRef = useRef(new Set());

  const startedAtRef = useRef(null);
  const recognitionStartRef = useRef(null);
  const submittedRef = useRef(false);
  const selectedIdsRef = useRef([]);
  // Mirrors `photoLibrary` for goToNextTrial to read at call time (see the
  // recognition-timer effect below) instead of closing over whichever
  // render's `photoLibrary` the timer's setInterval callback was created
  // with -- an async addPhotos() resolving mid-countdown must not be lost.
  const photoLibraryRef = useRef(photoLibrary);
  const clickHistoryRef = useRef([]);
  // §A.4 — scored trials' target faces, registered once we know whether
  // each was actually recognized in this same trial's own check.
  const registeredItemsRef = useRef([]);
  // Practice-trial outcomes, previously discarded once shown as feedback —
  // accumulated so the contract adapter can report them via
  // onPracticeComplete (§A.5).
  const practiceResultsRef = useRef([]);

  useEffect(() => { selectedIdsRef.current = selectedIds; }, [selectedIds]);
  // Assigned from a committed effect, not during render -- React can
  // replay or discard an in-progress render, and a ref write isn't rolled
  // back the way a state update would be, so writing it inline here could
  // leak a photo pool from a render that never actually committed
  // (CodeRabbit's review of this PR's earlier photoLibraryRef fix caught
  // this).
  useEffect(() => { photoLibraryRef.current = photoLibrary; }, [photoLibrary]);

  // (Preview note) No persisted store to load from — photoLibrary starts
  // empty and lives in React state only for the lifetime of this artifact.

  const openLibrary = useCallback(() => setScreen(SCREENS.LIBRARY), []);
  const closeLibrary = useCallback(() => setScreen(SCREENS.INSTRUCTIONS), []);

  const addPhotos = useCallback(async (fileList) => {
    const files = Array.from(fileList || []).filter((f) => f.type.startsWith("image/"));
    if (files.length === 0) return;
    setLibraryError(null);
    setLibraryBusy(true);
    try {
      const room = MAX_PATIENT_PHOTOS - photoLibrary.length;
      if (room <= 0) {
        setLibraryError(`You've reached the ${MAX_PATIENT_PHOTOS}-photo limit. Delete some to add more.`);
        return;
      }
      const toAdd = files.slice(0, room);
      const added = [];
      for (const file of toAdd) {
        // sequential, not parallel: keeps memory bounded when a patient
        // selects many large photos at once
        const dataURL = await downscaleImageFile(file, 240);
        const record = { id: uid("photo"), patientId: patientIdRef.current, dataURL, createdAt: Date.now() };
        added.push(record); // in-memory only in this preview — see note above
      }
      setPhotoLibrary((prev) => [...prev, ...added]);
      if (files.length > toAdd.length) {
        setLibraryError(`Only added ${toAdd.length} of ${files.length} photos — the ${MAX_PATIENT_PHOTOS}-photo limit was reached.`);
      }
    } catch {
      setLibraryError("One or more photos could not be read. Please try again.");
    } finally {
      setLibraryBusy(false);
    }
  }, [photoLibrary.length]);

  const deletePhoto = useCallback(async (photoId) => {
    setPhotoLibrary((prev) => prev.filter((p) => p.id !== photoId)); // in-memory only in this preview
  }, []);

  const totalScoredTrials = 5;

  const startAssessment = useCallback(() => {
    const practicePlan = buildPracticePlan();
    setPlan(practicePlan);
    setPhase("practice");
    setTrialIndex(0);
    setResponses([]);
    clickHistoryRef.current = [];
    usedPhotoIdsRef.current = new Set();
    startedAtRef.current = Date.now();
    // Practice trials are always synthetic (empty photo pool) so a
    // patient's own photos are reserved for the scored assessment.
    setTrialData(generateTrialData(practicePlan[0], [], usedPhotoIdsRef.current));
    setScreen(SCREENS.COUNTDOWN);
  }, []);

  const restartAssessment = useCallback(() => {
    setScreen(SCREENS.INSTRUCTIONS);
    setPhase("practice");
    setPlan([]);
    setTrialIndex(0);
    setTrialData(null);
    setSelectedIds([]);
    setResponses([]);
    clickHistoryRef.current = [];
    registeredItemsRef.current = [];
    practiceResultsRef.current = [];
    usedPhotoIdsRef.current = new Set();
    setResult(null);
    submittedRef.current = false;
  }, []);

  // countdown: 3, 2, 1, GO
  useEffect(() => {
    if (screen !== SCREENS.COUNTDOWN) return undefined;
    let value = 3;
    setCountdownValue(3);
    const interval = setInterval(() => {
      value -= 1;
      if (value >= 1) setCountdownValue(value);
      else if (value === 0) setCountdownValue("GO");
      else {
        clearInterval(interval);
        setSelectedIds([]);
        submittedRef.current = false;
        setScreen(SCREENS.OBSERVATION);
      }
    }, 650);
    return () => clearInterval(interval);
  }, [screen, trialIndex, phase]);

  // observation timer (viewing time)
  useEffect(() => {
    if (screen !== SCREENS.OBSERVATION || !trialData) return undefined;
    const total = trialData.config.viewingTimeSec;
    setTimeRemaining(total);
    const start = Date.now();
    const interval = setInterval(() => {
      const elapsed = (Date.now() - start) / 1000;
      const rem = Math.max(0, total - elapsed);
      setTimeRemaining(rem);
      if (rem <= 0) {
        clearInterval(interval);
        setScreen(SCREENS.DELAY);
      }
    }, 100);
    return () => clearInterval(interval);
  }, [screen, trialIndex, phase, trialData]);

  // delay timer (fixed 20s, blank screen)
  useEffect(() => {
    if (screen !== SCREENS.DELAY) return undefined;
    const total = DELAY_SEC;
    setTimeRemaining(total);
    const start = Date.now();
    const interval = setInterval(() => {
      const elapsed = (Date.now() - start) / 1000;
      const rem = Math.max(0, total - elapsed);
      setTimeRemaining(rem);
      if (rem <= 0) {
        clearInterval(interval);
        recognitionStartRef.current = Date.now();
        setScreen(SCREENS.RECOGNITION);
      }
    }, 100);
    return () => clearInterval(interval);
  }, [screen, trialIndex, phase]);

  // recognition timer (scales with study-face count, auto-submit on timeout)
  //
  // Deliberately NOT including `plan`/`photoLibrary` here the way
  // `submitSelections` below does: this effect's cleanup tears down and
  // restarts the countdown from `total` on every dependency change, so
  // adding `photoLibrary` would reset an in-progress countdown every time
  // an unrelated background photo upload (addPhotos) resolves. `plan` only
  // ever changes together with `phase` (continueFromFeedback sets both in
  // the same event), which is already listed, so it needs no ref.
  // `photoLibrary` doesn't have that guarantee -- an upload can resolve at
  // any point mid-countdown -- so `finishRecognition`'s timeout path reaches
  // `goToNextTrial` reading `photoLibraryRef.current` (see above) instead of
  // closing over a possibly-stale `photoLibrary`, without perturbing the
  // timer itself. CodeRabbit's review of PR #1 caught this: automatic
  // timeouts could otherwise score the next scored trial's photo pool
  // against a pre-upload snapshot even after the upload had finished.
  useEffect(() => {
    if (screen !== SCREENS.RECOGNITION || !trialData) return undefined;
    const total = trialData.config.recognitionMaxSec;
    setTimeRemaining(total);
    const start = Date.now();
    const interval = setInterval(() => {
      const elapsed = (Date.now() - start) / 1000;
      const rem = Math.max(0, total - elapsed);
      setTimeRemaining(rem);
      if (rem <= 0) {
        clearInterval(interval);
        finishRecognition(true);
      }
    }, 100);
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screen, trialIndex, phase, trialData]);

  const toggleSelect = useCallback((faceId) => {
    if (screen !== SCREENS.RECOGNITION) return;
    setSelectedIds((prev) => {
      const cap = trialData ? trialData.config.studyCount : 1;
      if (prev.includes(faceId)) return prev.filter((id) => id !== faceId);
      if (prev.length >= cap) return prev;
      return [...prev, faceId];
    });
  }, [screen, trialData]);

  function finishRecognition(timedOut) {
    if (submittedRef.current || !trialData) return;
    submittedRef.current = true;

    const currentSelected = selectedIdsRef.current;
    const reactionTimeMs = recognitionStartRef.current ? Date.now() - recognitionStartRef.current : 0;
    const validation = validateSelection(currentSelected, trialData.recognitionFaces);
    const config = trialData.config;

    const clicks = trialData.recognitionFaces
      .map((f) => ({ trialIndex, phase, faceId: f.id, wasTarget: f.isTarget, wasSelected: currentSelected.includes(f.id), timestamp: Date.now() }))
      .filter((c) => c.wasSelected);
    clickHistoryRef.current = [...clickHistoryRef.current, ...clicks];

    if (config.isPractice) {
      setLastFeedback({ ...validation, timedOut });
      practiceResultsRef.current = [
        ...practiceResultsRef.current,
        { reactionTimeMs, timedOut, correct: validation.fullyCorrect },
      ];
      setScreen(SCREENS.FEEDBACK);
    } else {
      const record = {
        trialIndex, difficulty: config.difficulty,
        targetsCount: validation.targetsCount, distractorsCount: validation.distractorsCount,
        hits: validation.hits, misses: validation.misses, falsePositives: validation.falsePositives,
        correctRejections: validation.correctRejections, fullyCorrect: validation.fullyCorrect,
        reactionTimeMs, timedOut,
      };

      // §A.4 — register this trial's study faces now, not at observation
      // time: only now do we know whether each was actually recognized.
      const registeredItems = trialData.studyFaces.map((f) => ({
        ...f,
        wasRecognizedAtEncoding: currentSelected.includes(f.id),
      }));
      registeredItemsRef.current = [...registeredItemsRef.current, ...registeredItems];
      StudyItemRegistry.register({ sourceModule: 'Face Recognition Test', itemType: 'face', items: registeredItems });

      setResponses((prev) => {
        const updated = [...prev, record];
        advanceAfterScoredTrial(updated);
        return updated;
      });
    }
  }

  // `finishRecognition` is a plain function (not memoized), so it's
  // technically a missing dependency here -- but every reactive value it
  // reads is already listed below, so `submitSelections` is already
  // recreated (recapturing the current `finishRecognition`) exactly when
  // any of them change. Adding `finishRecognition` itself would defeat
  // this memoization entirely, since a fresh function reference every
  // render would make `submitSelections` a new reference every render too.
  //
  // That "every reactive value" list is wider than it first looks: for a
  // scored trial, finishRecognition -> advanceAfterScoredTrial -> reads
  // `plan` -> goToNextTrial -> reads `photoLibrary`. `photoLibrary` in
  // particular was missing here until CodeRabbit's review of PR #1 caught
  // it -- a real bug, not just a lint nag: an async photo-library upload
  // resolving after this trial's `submitSelections` was memoized (but
  // before the patient tapped submit) would silently score the next
  // scored trial against a stale, pre-upload photo pool.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const submitSelections = useCallback(() => finishRecognition(false), [trialData, trialIndex, phase, plan, photoLibrary]);

  function goToNextTrial(nextPlan, nextIndex, nextPhase) {
    // Practice never draws from the patient's private photos — only the
    // scored assessment can be personalized. Reads the ref (not the
    // `photoLibrary` closure) so a call reached via the recognition timer's
    // possibly-stale `finishRecognition` closure (see that effect below)
    // still sees any photo uploaded since this render.
    const photoPool = nextPhase === "scored" ? photoLibraryRef.current : [];
    setPhase(nextPhase);
    setTrialIndex(nextIndex);
    setTrialData(generateTrialData(nextPlan[nextIndex], photoPool, usedPhotoIdsRef.current));
    submittedRef.current = false;
    setScreen(SCREENS.COUNTDOWN);
  }

  const continueFromFeedback = useCallback(() => {
    const practicePlan = plan;
    const nextIndex = trialIndex + 1;
    if (nextIndex < practicePlan.length) {
      goToNextTrial(practicePlan, nextIndex, "practice");
    } else {
      const scoredPlan = buildScoredPlan();
      setPlan(scoredPlan);
      usedPhotoIdsRef.current = new Set(); // fresh personalization budget for the scored run
      goToNextTrial(scoredPlan, 0, "scored");
    }
    // Same reasoning as submitSelections above: `goToNextTrial` is a plain
    // function whose only reactive read is `photoLibrary`, already listed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [plan, trialIndex, photoLibrary]);

  function advanceAfterScoredTrial(updatedResponses) {
    const nextIndex = trialIndex + 1;
    if (nextIndex < plan.length) {
      goToNextTrial(plan, nextIndex, "scored");
    } else {
      const finalResult = buildResultModel({
        sessionId: uid("session"), responses: updatedResponses, clickHistory: clickHistoryRef.current,
        startedAt: startedAtRef.current, completedAt: Date.now(),
      });
      setResult(finalResult);
      setScreen(SCREENS.COMPLETION);
    }
  }

  const progress = useMemo(() => {
    if (screen === SCREENS.INSTRUCTIONS) return 0;
    if (screen === SCREENS.COMPLETION) return 100;
    if (phase === "practice") return 4;
    return Math.round((trialIndex / totalScoredTrials) * 96) + 4;
  }, [screen, phase, trialIndex]);

  return {
    screen, phase, trialIndex, trialData, selectedIds, countdownValue, timeRemaining,
    lastFeedback, result, progress, totalScoredTrials,
    photoLibrary, libraryBusy, libraryError, patientId: patientIdRef.current,
    registeredItems: registeredItemsRef.current, practiceResults: practiceResultsRef.current,
    startAssessment, toggleSelect, submitSelections, continueFromFeedback, restartAssessment,
    openLibrary, closeLibrary, addPhotos, deletePhoto,
  };
}

/* ============================ Contract adapter ==============================
   See src/features/games/weekly/face-recognition/adapter.js for the
   mount/unmount wrapper this component gets rendered through. */
function toContractTrials(responses) {
  return responses.map((r) => ({
    responseTimeMs: r.reactionTimeMs,
    correct: r.fullyCorrect,
    errorType: r.fullyCorrect ? undefined : r.misses > 0 ? "miss" : r.falsePositives > 0 ? "false_positive" : undefined,
  }));
}
function toContractPracticeTrials(practiceResults) {
  return practiceResults.map((p) => ({
    responseTimeMs: p.reactionTimeMs,
    correct: p.correct,
    errorType: p.correct ? undefined : p.timedOut ? "timeout" : "incorrect_selection",
  }));
}

// registeredItems carries a full base64 dataURL for every "photo"-kind face
// (the built-in AI pool and any personalized upload) — fine for
// StudyItemRegistry.register() above, a same-tab sessionStorage bridge that
// never touches the network, but sending that same array to the backend as
// part of rawLog was the actual cause of the 413 "request entity too
// large" — real photo data was never supposed to leave the browser (see
// this file's own architecture note on Face Recognition uploads staying
// client-side/IndexedDB-only). Delayed Recognition's same-session retest
// already reads the untouched version straight from sessionStorage; the
// backend copy only needs enough to know an item existed and whether it
// was recognized, not its pixels.
function stripPhotoData(items) {
  return items.map((item) => {
    const copy = { ...item };
    delete copy.dataURL;
    return copy;
  });
}

/* ================================== App ==================================== */
export default function FaceRecognitionGame({ config, onComplete, onPracticeComplete }) {
  const test = useFaceRecognitionTest();
  const { screen, phase, trialIndex, trialData, selectedIds, countdownValue, timeRemaining,
          lastFeedback, result, progress, totalScoredTrials,
          photoLibrary, libraryBusy, libraryError, registeredItems, practiceResults,
          startAssessment, toggleSelect, submitSelections, continueFromFeedback, restartAssessment,
          openLibrary, closeLibrary, addPhotos, deletePhoto } = test;

  const reportedScoredRef = useRef(false);
  const reportedPracticeRef = useRef(false);

  useEffect(() => {
    if (screen === SCREENS.COMPLETION && result && !reportedScoredRef.current) {
      reportedScoredRef.current = true;
      onComplete?.({
        score: result.cognitiveScore,
        trials: toContractTrials(result.metrics.responses),
        studyItemsRegistered: registeredItems.map((i) => i.id),
        rawLog: { ...result, studyItems: stripPhotoData(registeredItems) },
      });
    }
  }, [screen, result, registeredItems, onComplete]);

  useEffect(() => {
    if (screen === SCREENS.COUNTDOWN && phase === "scored" && practiceResults.length > 0 && !reportedPracticeRef.current) {
      reportedPracticeRef.current = true;
      onPracticeComplete?.({ score: null, trials: toContractPracticeTrials(practiceResults) });
    }
  }, [screen, phase, practiceResults, onPracticeComplete]);
  void config;

  return (
    <div className="ntx-root">
      <style>{CSS}</style>

      <header className="app-topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true">
            <svg viewBox="0 0 24 24" width="18" height="18">
              <circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeWidth="1.6" />
              <path d="M8 13l2.2 2.4L16 9" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </span>
          <span className="brand-module">Face Recognition Memory Test</span>
        </div>
      </header>

      {screen !== SCREENS.INSTRUCTIONS && screen !== SCREENS.LIBRARY && screen !== SCREENS.COMPLETION && (
        <div className="progress-wrap">
          <div className="progress-track"><div className="progress-fill" style={{ width: `${progress}%` }} /></div>
        </div>
      )}

      <main className="app-main">
        {screen === SCREENS.INSTRUCTIONS && (
          <InstructionScreen onStart={startAssessment} onOpenLibrary={openLibrary} photoCount={photoLibrary.length} />
        )}
        {screen === SCREENS.LIBRARY && (
          <PhotoLibraryScreen
            photos={photoLibrary} busy={libraryBusy} error={libraryError} maxPhotos={MAX_PATIENT_PHOTOS}
            onAddFiles={addPhotos} onDelete={deletePhoto} onDone={closeLibrary}
          />
        )}
        {screen === SCREENS.COUNTDOWN && <CountdownScreen value={countdownValue} />}
        {screen === SCREENS.OBSERVATION && trialData && (
          <FaceObservationScreen trialData={trialData} timeRemaining={timeRemaining} trialIndex={trialIndex} totalScoredTrials={totalScoredTrials} phase={phase} />
        )}
        {screen === SCREENS.DELAY && <DelayScreen timeRemaining={timeRemaining} />}
        {screen === SCREENS.RECOGNITION && trialData && (
          <FaceRecognitionScreen
            trialData={trialData} selectedIds={selectedIds} onToggle={toggleSelect} onSubmit={submitSelections}
            timeRemaining={timeRemaining} trialIndex={trialIndex} totalScoredTrials={totalScoredTrials} phase={phase}
          />
        )}
        {screen === SCREENS.FEEDBACK && lastFeedback && <FeedbackScreen feedback={lastFeedback} onContinue={continueFromFeedback} />}
        {screen === SCREENS.COMPLETION && result && <CompletionScreen result={result} onRestart={restartAssessment} />}
      </main>
    </div>
  );
}

/* ================================== CSS ==================================== */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@500;600;700&display=swap');

:root{
  --paper:#F5F8FC;
  --panel:#FFFFFF;
  --ink:#0F2540;
  --ink-soft:#54647C;
  --line:#DDE5F0;
  --line-soft:#EAF0F8;
  --primary:#2E5FDC;
  --primary-dark:#1B3F9E;
  --primary-tint:#E9EFFC;
  --success:#12805A;
  --success-tint:#E1F5EC;
  --error:#C7433F;
  --error-tint:#FBEAE9;
  --warning:#B7791F;
  --warning-tint:#FBF1DE;
  --radius-lg:20px;
  --radius-md:14px;
  --radius-sm:10px;
  --shadow-card:0 1px 2px rgba(15,37,64,0.04),0 12px 32px -16px rgba(15,37,64,0.16);
  --font-display:'Sora',sans-serif;
  --font-body:'Inter',sans-serif;
  --font-mono:'JetBrains Mono',monospace;
}

.ntx-root{
  min-height:100vh; width:100%;
  background: radial-gradient(1100px 480px at 85% -10%, rgba(46,95,220,0.06), transparent 60%), var(--paper);
  color:var(--ink); font-family:var(--font-body);
  display:flex; flex-direction:column; box-sizing:border-box;
}
.ntx-root *{ box-sizing:border-box; }
.ntx-root button{ font-family:inherit; }
.ntx-root button:focus-visible{ outline:3px solid var(--primary); outline-offset:2px; }
@media (prefers-reduced-motion: reduce){ .ntx-root *{ animation-duration:0.001ms !important; transition-duration:0.001ms !important; } }

/* ---------------- Topbar / progress ---------------- */
.app-topbar{ display:flex; align-items:center; padding:18px 28px; border-bottom:1px solid var(--line); background:rgba(255,255,255,0.7); backdrop-filter:blur(6px); }
.brand{ display:flex; align-items:center; gap:10px; color:var(--ink); }
.brand-mark{ color:var(--primary); display:flex; }
.brand-module{ color:var(--ink-soft); font-size:14px; font-weight:500; }
.app-main{ flex:1; display:flex; }
.progress-wrap{ padding:0 28px; background:rgba(255,255,255,0.7); border-bottom:1px solid var(--line); }
.progress-track{ height:4px; background:var(--line); border-radius:4px; overflow:hidden; margin:12px 0; }
.progress-fill{ height:100%; background:linear-gradient(90deg,var(--primary),var(--primary-dark)); transition:width .4s ease; }

/* ---------------- Generic screen shells ---------------- */
.screen{ flex:1; width:100%; display:flex; }
.center-screen{ align-items:center; justify-content:center; padding:32px 20px; }
/* Was 44px 44px 38px — this screen in particular (intro paragraph, a
   3-item list, the personalize-with-photos panel, and the consent
   disclaimer, all before the button) ran taller than a typical laptop
   viewport, and scrolling to reach "Start Assessment" wasn't discoverable/
   reliable enough. Trimmed here and in .instruction-notes/.personalize-strip/
   .nt-disclaimer below so the whole card fits without depending on scroll. */
.card{ width:100%; background:var(--panel); border:1px solid var(--line); border-radius:var(--radius-lg); box-shadow:var(--shadow-card); padding:28px 32px 26px; }
.instructions-card{ max-width:660px; }
.completion-card{ max-width:920px; text-align:center; }

.eyebrow{ font-family:var(--font-mono); font-size:11.5px; letter-spacing:0.10em; text-transform:uppercase; color:var(--primary); font-weight:600; margin-bottom:14px; }
.display-xl{ font-family:var(--font-display); font-size:34px; line-height:1.15; margin:0 0 14px; letter-spacing:-0.01em; }
.display-lg{ font-family:var(--font-display); font-size:26px; line-height:1.2; margin:0 0 14px; letter-spacing:-0.01em; }
.lead{ font-size:16px; line-height:1.6; color:var(--ink-soft); margin:0 0 12px; max-width:60ch; }
.lead--tight{ margin:0 auto 22px; }

.instruction-notes{ list-style:none; padding:0; margin:6px 0 14px; display:flex; flex-direction:column; gap:8px; text-align:left; }
.instruction-notes li{ display:flex; align-items:flex-start; gap:10px; font-size:14px; color:var(--ink-soft); }
.instruction-notes li svg{ flex:0 0 auto; margin-top:2px; color:var(--primary); }

.nt-disclaimer{ margin:0 0 16px; padding:10px 14px; background:var(--primary-tint); border:1px solid #C8D7F7; border-radius:var(--radius-sm); font-size:12.5px; color:var(--ink-soft); line-height:1.5; text-align:left; }

/* ---------------- Buttons ---------------- */
.btn{ font-weight:600; border-radius:12px; border:1.5px solid transparent; cursor:pointer; transition:transform .12s ease, box-shadow .15s ease, background .15s ease, border-color .15s ease; font-size:14.5px; padding:12px 20px; }
.btn--primary{ background:var(--primary); color:#fff; box-shadow:0 10px 24px -10px rgba(46,95,220,0.55); }
.btn--primary:hover{ background:var(--primary-dark); transform:translateY(-1px); }
.btn--primary:active{ transform:translateY(0); }
.btn--large{ padding:16px 28px; font-size:16px; width:100%; }
.btn--ghost{ background:transparent; color:var(--ink-soft); border-color:var(--line); }
.btn--ghost:hover{ border-color:#B7C6EA; color:var(--ink); }
.row-actions{ display:flex; gap:12px; margin-top:8px; justify-content:center; }
.row-actions .btn--primary{ max-width:260px; }

/* ---------------- Countdown ---------------- */
.countdown-screen{ flex-direction:column; gap:22px; }
.countdown-ring{ width:180px; height:180px; border-radius:50%; border:2px solid var(--line); display:flex; align-items:center; justify-content:center; background:var(--panel); box-shadow:var(--shadow-card); }
.countdown-num{ font-family:var(--font-display); font-size:64px; font-weight:700; color:var(--primary); animation:ntxFade .38s ease; }
.countdown-go{ color:var(--success); font-size:44px; letter-spacing:0.04em; }
.countdown-caption{ color:var(--ink-soft); font-size:14px; }
@keyframes ntxFade{ from{ opacity:0; transform:scale(0.85);} to{ opacity:1; transform:scale(1);} }

/* ---------------- Trial header / HUD ---------------- */
.assessment-screen{ flex-direction:column; padding:24px 26px 34px; gap:16px; max-width:840px; margin:0 auto; }
.hud{ display:grid; grid-template-columns:1fr 1fr 1.4fr; gap:1px; background:var(--line); border:1px solid var(--line); border-radius:var(--radius-md); overflow:hidden; }
.hud-item{ background:var(--panel); padding:12px 16px; display:flex; flex-direction:column; gap:6px; }
.hud-label{ font-size:11px; text-transform:uppercase; letter-spacing:0.06em; color:var(--ink-soft); font-weight:600; display:flex; align-items:center; gap:5px; }
.hud-label svg{ color:var(--primary); }
.hud-value{ font-family:var(--font-display); font-size:15px; font-weight:600; color:var(--ink); }
.hud-mono{ font-family:var(--font-mono); font-size:16px; }

.nt-chip{ display:inline-block; font-size:11px; font-weight:700; padding:5px 11px; border-radius:100px; letter-spacing:0.04em; text-transform:uppercase; width:fit-content; }
.nt-chip-easy{ background:var(--success-tint); color:var(--success); }
.nt-chip-medium{ background:var(--warning-tint); color:var(--warning); }
.nt-chip-hard{ background:var(--error-tint); color:var(--error); }
.nt-chip-practice{ background:var(--primary-tint); color:var(--primary); }

.timer-wrap{ display:flex; align-items:center; gap:8px; }
.timer-track{ flex:1; height:6px; background:var(--line-soft); border-radius:6px; overflow:hidden; }
.timer-fill{ height:100%; background:var(--primary); transition:width .2s linear; }
.timer-fill--low{ background:var(--error); }
.timer-text{ font-family:var(--font-mono); font-size:13px; font-weight:700; color:var(--ink); width:34px; text-align:right; }

.instruction-strip{ text-align:center; font-size:13.5px; color:var(--ink-soft); margin:0; font-weight:500; }
.instruction-strip b{ color:var(--ink); }

/* ---------------- Face grids ---------------- */
.face-grid{ display:grid; gap:20px; justify-content:center; margin:6px auto; }
.face-grid .face-card{ width:180px; }
.recog-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(120px,1fr)); gap:16px; margin:6px 0 8px; }

.face-card{ background:linear-gradient(180deg,#F7FAFD,#EDF3F9); border-radius:14px; border:1px solid var(--line); display:flex; align-items:center; justify-content:center; aspect-ratio:1/1; overflow:hidden; position:relative; }
.face-card svg{ width:100%; height:100%; display:block; }
.face-card--selectable{ cursor:pointer; transition:transform .15s ease, box-shadow .15s ease; }
.face-card--selectable:hover{ transform:translateY(-2px); box-shadow:var(--shadow-card); }
.face-card--selected{ box-shadow:0 0 0 3px var(--primary), var(--shadow-card); }
.face-card--selected::after{ content:'\\2713'; position:absolute; top:8px; right:8px; width:22px; height:22px; border-radius:50%; background:var(--primary); color:white; font-size:12px; font-weight:800; display:flex; align-items:center; justify-content:center; }

/* ---------------- Delay ---------------- */
.delay-screen{ flex-direction:column; gap:22px; }
.delay-pulse{ width:64px; height:64px; border-radius:50%; background:var(--primary-tint); display:flex; align-items:center; justify-content:center; position:relative; }
.delay-pulse::before{ content:''; position:absolute; inset:0; border-radius:50%; background:var(--primary-tint); animation:ntxRipple 1.8s ease-out infinite; }
.delay-pulse-core{ width:14px; height:14px; border-radius:50%; background:var(--primary); z-index:1; }
@keyframes ntxRipple{ 0%{ transform:scale(1); opacity:0.6; } 100%{ transform:scale(2.4); opacity:0; } }
.delay-text{ color:var(--ink-soft); font-size:14px; font-weight:500; }

/* ---------------- Feedback ---------------- */
.feedback-banner{ margin-top:18px; padding:14px 18px; border-radius:12px; font-size:14px; font-weight:600; }
.feedback-banner--correct{ background:var(--success-tint); color:var(--success); }
.feedback-banner--incorrect{ background:var(--error-tint); color:var(--error); }

/* ---------------- Completion ---------------- */
.completion-badge{ width:52px; height:52px; border-radius:50%; background:var(--success-tint); color:var(--success); display:flex; align-items:center; justify-content:center; margin:0 auto 18px; }

.score-ring-panel{ display:flex; align-items:center; gap:24px; justify-content:center; background:linear-gradient(135deg,var(--primary-tint),var(--panel)); border:1px solid #C8D7F7; border-radius:var(--radius-md); padding:22px 26px; margin-bottom:26px; text-align:left; }
.score-ring{ position:relative; width:132px; height:132px; flex:none; }
.score-ring-label{ position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center; }
.score-ring-num{ font-family:var(--font-display); font-size:30px; font-weight:800; color:var(--primary-dark); }
.score-ring-sub{ font-size:10px; color:var(--ink-soft); text-transform:uppercase; letter-spacing:0.08em; }
.score-ring-meta{ max-width:420px; }
.interpretation-text{ font-size:14px; color:var(--ink-soft); line-height:1.6; margin:8px 0 0; }

.severity-badge{ display:inline-block; padding:5px 13px; border-radius:100px; font-size:12px; font-weight:700; }
.severity-badge--normal{ background:var(--success-tint); color:var(--success); }
.severity-badge--mild-concern{ background:var(--warning-tint); color:var(--warning); }
.severity-badge--moderate-concern{ background:var(--warning-tint); color:var(--warning); }
.severity-badge--significant-concern{ background:var(--error-tint); color:var(--error); }

.metrics-grid{ display:grid; grid-template-columns:repeat(auto-fill,minmax(180px,1fr)); gap:12px; margin-bottom:24px; text-align:left; }
.metric-tile{ background:var(--paper); border:1px solid var(--line); border-radius:var(--radius-sm); padding:14px 16px; display:flex; flex-direction:column; gap:6px; }
.metric-label{ font-size:11px; color:var(--ink-soft); text-transform:uppercase; letter-spacing:0.05em; font-weight:600; }
.metric-value{ font-size:19px; font-weight:800; color:var(--ink); }
.metric-unit{ font-size:11px; color:var(--ink-soft); font-weight:600; margin-left:2px; }

.dashboard-section{ margin-bottom:22px; text-align:left; }
.dashboard-section-title{ font-size:14.5px; font-weight:700; color:var(--ink); margin:0 0 12px; }
.chart-legend{ display:flex; gap:16px; margin-top:10px; flex-wrap:wrap; }
.legend-item{ display:flex; align-items:center; gap:6px; font-size:11.5px; color:var(--ink-soft); }
.legend-item i{ width:9px; height:9px; border-radius:3px; display:inline-block; }

/* ---------------- Responsive ---------------- */
@media (max-width: 720px){
  .card{ padding:30px 22px 26px; }
  .display-xl{ font-size:27px; }
  .hud{ grid-template-columns:1fr 1fr; }
  .metrics-grid{ grid-template-columns:1fr 1fr; }
  .face-grid .face-card{ width:130px; }
  .app-topbar{ padding:14px 18px; }
  .score-ring-panel{ flex-direction:column; text-align:center; }
  .score-ring-meta{ text-align:center; }
}
@media (max-width: 420px){
  .metrics-grid{ grid-template-columns:1fr; }
  .row-actions{ flex-direction:column-reverse; }
}

/* ---------------- Face photo rendering ---------------- */
.face-photo-img{
  width:100%; height:100%; object-fit:cover; display:block;
  -webkit-user-select:none; user-select:none; -webkit-user-drag:none;
}

/* ---------------- Personalization entry point (instructions) ---------------- */
.personalize-strip{
  display:flex; align-items:center; justify-content:space-between; gap:16px;
  background:var(--paper); border:1px solid var(--line); border-radius:var(--radius-md);
  padding:12px 16px; margin:6px 0 14px; text-align:left;
}
.personalize-title{ font-weight:700; font-size:14px; color:var(--ink); }
.personalize-optional{ font-weight:500; color:var(--ink-soft); font-size:12px; }
.personalize-sub{ font-size:12.5px; color:var(--ink-soft); margin-top:4px; max-width:46ch; }

/* ---------------- Photo library screen ---------------- */
.library-card{ max-width:640px; text-align:left; }
.library-upload-row{ display:flex; align-items:center; gap:14px; margin:4px 0 16px; }
.library-count{ font-size:13px; color:var(--ink-soft); }
.library-error{ background:var(--error-tint); color:var(--error); border-radius:var(--radius-sm); padding:10px 14px; font-size:13px; margin-bottom:16px; }
.library-empty{ font-size:13.5px; color:var(--ink-soft); margin:0 0 20px; }
.library-grid{ display:grid; grid-template-columns:repeat(auto-fill,minmax(84px,1fr)); gap:10px; margin-bottom:24px; }
.library-thumb{ position:relative; aspect-ratio:1/1; border-radius:10px; overflow:hidden; border:1px solid var(--line); }
.library-thumb img{ width:100%; height:100%; object-fit:cover; display:block; -webkit-user-select:none; user-select:none; }
.library-thumb-remove{
  position:absolute; top:4px; right:4px; width:20px; height:20px; border-radius:50%;
  background:rgba(15,37,64,0.65); color:#fff; border:none; cursor:pointer;
  font-size:14px; line-height:1; display:flex; align-items:center; justify-content:center;
}
.library-thumb-remove:hover{ background:var(--error); }
`;
